#include <array>
#include <vector>
#include <cstddef>
#include <omp.h>

void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    bins.fill(0);

    const std::ptrdiff_t n = static_cast<std::ptrdiff_t>(x.size());

    #pragma omp parallel default(none) shared(x, bins, n)
    {
        std::array<size_t, 10> local_bins{};
        local_bins.fill(0);

        #pragma omp for nowait
        for (std::ptrdiff_t i = 0; i < n; ++i) {
            const double v = x[static_cast<std::size_t>(i)];

            // Input is specified to be in [0, 100], but keep this robust.
            if (v < 0.0 || v > 100.0) {
                continue;
            }

            const std::size_t idx =
                (v >= 100.0) ? 9u : static_cast<std::size_t>(v / 10.0);

            ++local_bins[idx];
        }

        #pragma omp critical
        {
            for (std::size_t j = 0; j < 10; ++j) {
                bins[j] += local_bins[j];
            }
        }
    }
}
